      { question: "Midjourney V7 相比 V6 有哪些提升？", answer: "V7 的核心升级包括：Consistency Model（多次生成保持角色/场景风格统一）、Personalization 2.0（根据历史偏好调整输出风格）、原生 4K 分辨率输出、以及 Re-texturing Mode（保持原图结构只改材质纹理）。" }
