      { question: "Figma Config 2026 最值得关注的功能是什么？", answer: "最值得关注的是 Code Layers（将代码作为设计原生图层）和 Figma Motion（原生时间轴动效编辑器），它们从根本上改变了设计与开发的协作方式。" }
