      { question: "OpenDesign 是什么？", answer: "OpenDesign 是一个 GitHub 超 8.4 万 Star 的开源项目，可调用 Claude Code、Codex、Cursor 等 Coding Agent，把代码能力与设计系统结合，生成网页、原型、PPT、图片和视频。" }
