      { question: "GPT Image 2.5 的 Flare 和 Sunburst 有什么区别？", answer: "Flare 是通用快速版，适合社交媒体素材和大批量生成；Sunburst 主打高精度精细编辑，面向广告大片和商业产品图，生成耗时更长但可控性更强。" },
      { question: "Figma 的生成式插件现在能做什么？", answer: "除了用自然语言生成自定义插件，现在还支持动画/交互 Shader、社区发布、代码查看以及通过 MCP 让第三方 AI 智能体查看和修改。" }
