      { question: "Qwen-Image 2.1 有什么特点？", answer: "阿里巴巴 9 月 21 日发布的 Qwen-Image 2.1 是 70 亿参数的开源图像生成模型，小参数量降低了本地化部署门槛，为设计团队提供了可自主掌控、可定制微调的生成方案。" },
      { question: "美图设计室的 AI Agent 能做什么？", answer: "在 2026 服贸会上展示的全链路商业设计能力：用户用自然语言描述需求，多个专业智能体协同完成策略规划、信息研究、视觉制作到交付的完整流程，覆盖电商与品牌传播场景。" }
