      { question: "Figma 的动画样式更新对设计师有什么用？", answer: "自定义动画样式可保存并发布到团队库，Figma 智能体与外部编码智能体能通过 MCP 自动应用、也能在 skills 中被引用，动效规格从此成为设计系统里可被机器消费的一等资产。" },
      { question: "Midjourney 这次更新了什么？", answer: "Alpha 版本新增实时风格预览、默认参数保存、项目删除撤销、编辑历史方向键导航，以及定向编辑时保护选区外像素的新编辑模型，重点在提升可控性而非画质。" }
