    title: "AI 设计日报 | 2026年10月08日 - Figma AI Agent 正式商用, Anthropic 推出 Claude Design",
    description: "Figma AI Agent 结束测试并全面开放，Anthropic 推出 Claude Design 布局工具，阿里开源 Qwen-Image-Layered 分层图像模型，Sketch 与 Canva 也有新动作。",
    content: "## 今日要点\n\n- **Figma AI Agent 正式 GA**：10 月 6 日起结束测试，全面开放并开始消耗 AI credits，支持设计库 Markdown 指南、跨文件搜索和实时协作视图。\n- **Anthropic Claude Design 登场**：基于 Claude Opus 4.7，可从文本提示生成品牌一致的网页、幻灯片和广告素材。\n- **阿里开源 Qwen-Image-Layered**：首次实现 AI 原生分层编辑，支持图层级位移、缩放与重绘。\n- **Sketch 2026.1.1 更新**：新增选区颜色、独立边框、检查模式完整图层列表等细节改进。\n\n## Figma AI Agent 走出测试，进入付费时代\n\nFigma 的 AI Agent 在 10 月 6 日正式结束 beta 阶段，向 Professional、Organization 和 Enterprise 用户全面开放。主要变化包括：\n\n- **设计库指南**：允许上传 Markdown 文件，描述组件、颜色和反模式规则，Agent 每次调用库时都会读取。\n- **实时协作视图**：可以看到队友的 Agent 正在画布上执行什么操作。\n- **文件内搜索**：支持在对话中搜索并引用 Figma Design、FigJam 和 Figma Slides 的内容。\n- **生成式插件 GA**：可直接在画布上选择图像模型进行编辑。\n- **开始计费**：Agent 与 Figma Make 共享 AI credits 池，预算需要重新评估。\n\n根据 Figma 官方评估，新 Agent 在专业设计师的对比评测中胜率超过 60%，但在复杂设计系统下的遵循度仍有提升空间。\n\n## Anthropic Claude Design：把品牌系统变成可复用工作流\n\nAnthropic 发布了 **Claude Design**，定位为面向营销和产品的可视化布局工具。核心亮点：\n\n- 通过拖拽 Logo、色板和网址，几分钟内建立 design.md 品牌系统文件。\n- 支持生成网页、落地页、幻灯片和社媒轮播图，可导出为 HTML、PDF、PPTX 或 Canva。\n- 与 ChatGPT 或 Midjourney 搭配使用，生成符合品牌色值的图像。\n- 目前处于研究预览阶段，仅消耗已有 Claude credits，无单独计费。\n\n对小型团队和独立创作者来说，这套工具把「品牌一致性」从设计师手中部分释放出来，但审美判断和最终决策仍不可替代。\n\n## 阿里开源 Qwen-Image-Layered：AI 图像也能分层编辑\n\n阿里近日开源了 **Qwen-Image-Layered** 图像模型，首次让 AI 生成的图片具备类似 Photoshop 的原生图层理解能力。这意味着：\n\n- 调整画面中的某个元素时，不必全图重绘。\n- 可在保留其他图层不变的前提下，对特定对象进行位移、缩放和重绘。\n- 对电商海报、UI 界面等需要反复修改的商业设计场景尤为实用。\n\n该模型免费开源可商用，但本地部署对算力有一定要求，适合有技术储备的团队尝试。\n\n## 其他值得关注的工具动态\n\n- **Sketch 2026.1.1**：新增选区颜色、独立边框控制、圆角平滑和检查模式下的完整图层列表，继续稳扎稳打。\n- **Canva Create 2026**：Affinity 接入 Canva Brand System 和 Claude AI 连接器，Cavalry 向所有 Canva 用户免费开放。\n- **Midjourney V8.1 Alpha**：HD 模式速度提升 3 倍、成本降低 3 倍，标准分辨率也快了 50%。\n\n## 今日总结\n\n今天的设计工具新闻集中在两个方向：一是 **Agent 深度嵌入现有工作流**（Figma、Claude），二是 **AI 图像编辑的可控性**（Qwen-Image-Layered 的分层能力）。对设计师而言，重复性劳动会继续被压缩，但品味判断、品牌理解和复杂决策的价值反而在上升。",
    author: "AI Design Hub",
    author_avatar: "https://ui-avatars.com/api/?name=AI+Hub&background=8b5cf6&color=fff",
