    seo_description: "AI 设计日报 2026年10月21日：Meshy 发布圈选式局部编辑功能 Meshy Edit，Lovart 2.0 推出个人设计 Agent Arti，Figma 新增 20 个 MCP 合作伙伴。每日 AI 设计新闻速览。",
