      { question: "Canva Craft 和其他图像模型有什么不同？", answer: "Craft 采用两段式架构，先规划版面结构、元素层级与文字位置，再进行渲染，训练数据来自 Canva 平台上百万套人工设计模板，因此更擅长海报、幻灯片、信息图这类排版密集的商业设计场景，输出可一键拆成可编辑分层文件。" }
