      { question: "Figma 这次的更新对设计师有什么用？", answer: "10 月 27 日起生成式插件和着色器有了版本历史，每次编辑生成新版本且可回滚，每个版本附带 agent 生成的变更说明；版本视图会标出当前已发布的版本。同期 MCP 可调用 Weave 的 Seedance、Kling、Nano Banana 模型，并在 Config India 新增 html_to_figma 工具。" },
      { question: "MOSS-Image 适合什么场景？", answer: "适合海报、信息图、漫画、UI 稿等文字多、版式敏感的项目。它 5B 参数、Apache-2.0 开源，支持 JSON 布局用边界框精确控制元素位置，可渲染中英文长文本；但目前只支持文生图，不吃参考图，也没有原生编辑能力。" }
